75	static libzippp_uint16 convertCompressionToLibzip(CompressionMethod comp) {
76	    switch(comp) {
77	        case CompressionMethod::STORE:
78	            return ZIP_CM_STORE;
79	#ifdef ZIP_CM_BZIP2
80	        case CompressionMethod::BZIP2:
81	            return ZIP_CM_BZIP2;
82	#endif
83	        case CompressionMethod::DEFLATE:
84	            return ZIP_CM_DEFLATE;
85	#ifdef ZIP_CM_XZ
86	        case CompressionMethod::XZ:
87	            return ZIP_CM_XZ;
88	#endif
89	#ifdef ZIP_CM_ZSTD
90	        case CompressionMethod::ZSTD:
91	            return ZIP_CM_ZSTD;
92	#endif
93	        default:
94	            return ZIP_CM_DEFAULT;
95	    }
96	}
