121	/*
122	 * ZIP_CM_DEFAULT is defined as -1 by libzip. libzippp stores the compression methods as
123	 * unsigned 16-bit values, which turns it into 65535: the value must be sign-extended back
124	 * before being handed to libzip, otherwise it is rejected as an unknown method.
125	 */
126	static zip_int32_t compressionMethodToLibzip(libzippp_uint16 comp) {
127	    return (zip_int32_t)(zip_int16_t)comp;
128	}
