130	/*
131	 * Returns true if the compression level can be used with the compression method. A zero
132	 * level always means the default behaviour of libzip. libzip accepts an out-of-range
133	 * DEFLATE level without complaining (and would silently write it), so the documented
134	 * 1-9 range is enforced here. ZIP_CM_DEFAULT resolves to DEFLATE when the changes are
135	 * written and is checked against the same range. The other combinations are validated
136	 * by libzip itself.
137	 */
138	static bool isCompressionLevelApplicable(libzippp_uint16 comp, libzippp_uint32 level) {
139	    if (level==0) { return true; }
140	    if (comp==(libzippp_uint16)ZIP_CM_DEFLATE || comp==(libzippp_uint16)ZIP_CM_DEFAULT) { return level<=9; }
141	    return true;
142	}
