145	    static void callErrorHandlingCallbackFunc(const std::string& message, int zip_error_code, int system_error_code, ErrorHandlerCallback* callback) {
146	        zip_error_t error;
147	        zip_error_init(&error);
148	        zip_error_set(&error, zip_error_code, system_error_code);
149	        std::string strerror(zip_error_strerror(&error));
150	        (*callback)(message, strerror, zip_error_code, system_error_code);
151	        zip_error_fini(&error);
152	    }
153	
154	    static void callErrorHandlingCallback(zip* zipHandle, const std::string& msg, ErrorHandlerCallback* callback) {
155	        if (zipHandle!=nullptr) {
156	            zip_error_t* error_code = zip_get_error(zipHandle);
157	            callErrorHandlingCallbackFunc(msg, error_code->zip_err, error_code->sys_err, callback);
158	        } else {
159	            callErrorHandlingCallbackFunc("", -1, -1, callback);
160	        }
161	    }
