164	        int error_code_zip, error_code_system;
165	        error_code_zip = zip_error_code_zip(error);
166	        error_code_system = zip_error_code_system(error);
167	        callErrorHandlingCallbackFunc(msg, error_code_zip, error_code_system, callback);
