179	/*
180	 * State of the custom zip_source backing an entry staged from an std::istream
181	 * (see ZipArchive::addData(const std::string&, std::istream&, ...)). The content
182	 * lives in a temporary file created with tmpfile(): it is removed by the operating
183	 * system as soon as the file is closed, and the FILE* is owned and closed by the
184	 * ZipArchive (see stagedStreamFiles), never by this source. The source itself only
185	 * owns this small state, which is released when libzip frees the source.
186	 */
187	struct IstreamSourceState {
188	    FILE* file;
189	    libzippp_uint64 size;
190	    libzippp_uint64 offset;
191	    zip_error_t error;
192	};
193	
194	static int seekIstreamSourceFile(FILE* file, libzippp_uint64 offset) {
195	#ifdef _WIN32
196	    return _fseeki64(file, (__int64)offset, SEEK_SET);
197	#else
198	    return fseek(file, (long)offset, SEEK_SET);
199	#endif
200	}
201	
202	static zip_int64_t istreamSourceCallback(void* userdata, void* data, zip_uint64_t len, zip_source_cmd_t cmd) {
203	    IstreamSourceState* state = static_cast<IstreamSourceState*>(userdata);
204	    switch (cmd) {
205	        case ZIP_SOURCE_OPEN:
206	            //a staged source is (re)opened for every read of the entry and for every
207	            //commit attempt (a cancelled commit may be retried): always restart from
208	            //the beginning of the staged content
209	            if (seekIstreamSourceFile(state->file, 0)!=0) {
210	                zip_error_set(&state->error, ZIP_ER_SEEK, errno);
211	                return -1;
212	            }
213	            state->offset = 0;
214	            return 0;
215	
216	        case ZIP_SOURCE_READ: {
217	            zip_uint64_t remaining = state->size - state->offset;
218	            zip_uint64_t toRead = len<remaining ? len : remaining;
219	            if (toRead==0) { return 0; }
220	            size_t got = fread(data, 1, (size_t)toRead, state->file);
221	            state->offset += got;
222	            if (got<(size_t)toRead && ferror(state->file)) {
223	                zip_error_set(&state->error, ZIP_ER_READ, errno);
224	                return -1;
225	            }
226	            return (zip_int64_t)got;
227	        }
228	
229	        case ZIP_SOURCE_CLOSE:
230	            //the staging file stays open: it belongs to the archive, which closes it
231	            //when the pending changes are committed, abandoned or destroyed
232	            return 0;
233	
234	        case ZIP_SOURCE_STAT: {
235	            if (len<sizeof(zip_stat_t)) {
236	                zip_error_set(&state->error, ZIP_ER_INVAL, 0);
237	                return -1;
238	            }
239	            //mirrors the stat of a buffer source: the staged content is the raw,
240	            //uncompressed and unencrypted data of the entry
241	            zip_stat_t* st = (zip_stat_t*)data;
242	            zip_stat_init(st);
243	            st->size = state->size;
244	            st->comp_size = state->size;
245	            st->comp_method = ZIP_CM_STORE;
246	            st->encryption_method = ZIP_EM_NONE;
247	            st->valid = ZIP_STAT_SIZE | ZIP_STAT_COMP_SIZE | ZIP_STAT_COMP_METHOD | ZIP_STAT_ENCRYPTION_METHOD;
248	            return sizeof(zip_stat_t);
249	        }
250	
251	        case ZIP_SOURCE_ERROR:
252	            return zip_error_to_data(&state->error, data, len);
253	
254	        case ZIP_SOURCE_FREE:
255	            //only the state belongs to the source; the staging file is closed by the
256	            //archive (see stagedStreamFiles), never here
257	            delete state;
258	            return 0;
259	
260	        case ZIP_SOURCE_SEEK: {
261	            zip_int64_t newOffset = zip_source_seek_compute_offset(state->offset, state->size, data, len, &state->error);
262	            if (newOffset<0) { return -1; }
263	            if (seekIstreamSourceFile(state->file, (libzippp_uint64)newOffset)!=0) {
264	                zip_error_set(&state->error, ZIP_ER_SEEK, errno);
265	                return -1;
266	            }
267	            state->offset = (libzippp_uint64)newOffset;
268	            return 0;
269	        }
270	
271	        case ZIP_SOURCE_TELL:
272	            return (zip_int64_t)state->offset;
273	
274	        case ZIP_SOURCE_SUPPORTS:
275	            //seekable, and re-openable so that the staged entry can be read back
276	            //(Current state) and committed as many times as needed
277	            return ZIP_SOURCE_SUPPORTS_SEEKABLE | ZIP_SOURCE_MAKE_COMMAND_BITMASK(ZIP_SOURCE_SUPPORTS_REOPEN);
278	
279	        default:
280	            zip_error_set(&state->error, ZIP_ER_OPNOTSUPP, 0);
281	            return -1;
282	    }
283	}
