341	basic_string<libzippp_uint8> ZipEntry::readAsBinaryString(ZipArchive::State state, libzippp_uint64 size) const {
342	    if (isNull()) { return basic_string<libzippp_uint8>(); }
343	    if (session.expired()) { return basic_string<libzippp_uint8>(); }
344	    libzippp_uint8* content = (libzippp_uint8*)zipFile->readEntry(*this, true, state, size);
345	    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed or the entry does not exist in the state
346	
347	    //see readAsText: the length must reflect the requested state (zero bytes inside the
348	    //content are preserved, the extra '\0' is only an allocation artifact)
349	    libzippp_uint64 maxSize = zipFile->getEntry((libzippp_int64)index, state).getSize();
350	    libzippp_uint64 length = size==0 || size>maxSize ? maxSize : size;
351	    basic_string<libzippp_uint8> str(content, length);
352	    delete[] content;
353	    return str;
354	}
