356	int ZipEntry::readContent(std::ostream& ofOutput, ZipArchive::State state, libzippp_uint64 chunksize) const {
357	   //an invalid stream is reported first, as for a valid entry; the error codes below
358	   //are the ones guaranteed when the stream itself is valid
359	   if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
360	   //a null entry is invalid; a non-null entry whose opening ended is reported as coming
361	   //from a no-longer-open archive. The archive object itself may have been destroyed,
362	   //hence these checks must not dereference zipFile.
363	   if (isNull()) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
364	   if (session.expired()) { return LIBZIPPP_ERROR_NOT_OPEN; }
365	   return zipFile->readEntry(*this, ofOutput, state, chunksize);
366	}
