391	void ZipArchive::beginEntrySession(void) {
392	    entrySession = std::make_shared<ZipEntrySession>();
393	    //the compression configuration staged on individual entries belongs to the opening
394	    //it was made in: a new opening never inherits the levels recorded previously
395	    entryCompressionMethods.clear();
396	    entryCompressionLevels.clear();
397	}
