405	bool ZipArchive::isEntryUsable(const ZipEntry& entry) const {
406	    if (entry.isNull()) { return false; }
407	    if (entry.zipFile!=this) { return false; }
408	    //the entry must belong to the CURRENT opening of this archive: its session marker
409	    //is the one this archive holds right now
410	    std::shared_ptr<ZipEntrySession> entryOpening = entry.session.lock();
411	    return entryOpening && entryOpening==entrySession;
412	}
