414	ZipArchive::~ZipArchive(void) {
415	    close(); /* discard ??? */
416	
417	    //if the commit failed in close(), the archive is gone anyway: the adopted buffers
418	    //must not outlive it (on a successful close/discard this is a no-op)
419	    releaseAdoptedBuffers();
420	
421	    //same for the files staging stream-written entries (see stagedStreamFiles)
422	    releaseStagedStreamFiles();
423	
424	    //whatever close() did (including a failed commit), the archive object itself is
425	    //gone: every entry obtained from any opening must be expired now
426	    endEntrySession();
427	
428	    // ensures all the values are clared
429	    zipHandle = nullptr;
430	    zipSource = nullptr;
431	    bufferData = nullptr;
432	    errorHandlingCallback = nullptr;
433	    listeners.clear();
434	}
