474	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
475	    zip_error_t error;
476	    zip_error_init(&error);
477	
478	    /* create source from buffer */
479	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
480	    if (localZipSource == nullptr) {
481	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
482	        zip_error_fini(&error);
483	        return false;
484	    }
485	
486	    bool open = openSource(localZipSource, om, checkConsistency);
487	    if (open) {
488	        if (om==Write || om==New) {
489	            bufferData = data;
490	            bufferLength = size;
491	
492	            //prevents libzip to delete the source when closing the ZipArchive
493	            zip_source_keep(localZipSource);
494	        }
495	    } else {
496	        zip_source_free(localZipSource);
497	        localZipSource = nullptr;
498	    }
499	    return open;
500	}
501	
502	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
503	    int zipFlag = 0;
504	    if (om == ReadOnly) { zipFlag = 0; }
505	    else if (om == Write) { zipFlag = ZIP_CREATE; }
506	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
507	    else { return false; }
508	    if (checkConsistency) {
509	        zipFlag = zipFlag | ZIP_CHECKCONS;
510	    }
511	
512	    zip_error_t error;
513	    zip_error_init(&error);
514	
515	    /* open zip archive from source */
516	    zipHandle = zip_open_from_source(source, zipFlag, &error);
517	    if (zipHandle == nullptr) {
518	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
519	        zip_error_fini(&error);
520	        return false;
521	    }
522	    zip_error_fini(&error);
523	
524	    zipSource = source;
525	
526	#ifdef LIBZIPPP_WITH_ENCRYPTION
527	    if (isEncrypted()) {
528	        int result = zip_set_default_password(zipHandle, password.c_str());
529	        if (result != 0) {
530	            close();
531	            return false;
532	        }
533	    }
534	#endif
535	
536	    mode = om;
537	    beginEntrySession(); //entries created by this opening share this marker
538	    return true;
539	}
