541	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
542	    if (isOpen()) { return om==mode; }
543	
544	    int zipFlag = 0;
545	    if (om==ReadOnly) { zipFlag = 0; }
546	    else if (om==Write) { zipFlag = ZIP_CREATE; }
547	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
548	    else { return false; }
549	
550	    if (checkConsistency) {
551	        zipFlag = zipFlag | ZIP_CHECKCONS;
552	    }
553	
554	    int errorFlag = 0;
555	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
556	
557	    //error during opening of the file
558	    if (errorFlag!=ZIP_ER_OK) {
559	        zip_error_t error;
560	        zip_error_init_with_code(&error, errorFlag);
561	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
562	        zip_error_fini(&error);
563	
564	        zipHandle = nullptr;
565	        return false;
566	    }
567	
568	    if (zipHandle!=nullptr) {
569	#ifdef LIBZIPPP_WITH_ENCRYPTION
570	        if (isEncrypted()) {
571	            int result = zip_set_default_password(zipHandle, password.c_str());
572	            if (result!=0) {
573	                close();
574	                return false;
575	            }
576	        }
577	#endif
578	
579	        mode = om;
580	        beginEntrySession(); //entries created by this opening share this marker
581	        return true;
582	    }
583	
584	    return false;
585	}
