587	void progress_callback(zip* /*archive*/, double progression, void* ud) {
588	    ZipArchive* za = static_cast<ZipArchive*>(ud);
589	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
590	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
591	        ZipProgressListener* listener = *it;
592	        listener->progression(progression);
593	    }
594	}
595	
596	int progress_cancel_callback(zip* /*archive*/, void* ud) {
597	    ZipArchive* za = static_cast<ZipArchive*>(ud);
598	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
599	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
600	        ZipProgressListener* listener = *it;
601	        if (listener->cancel())
602	          return 1;
603	    }
604	    return 0;
605	}
606	
607	int ZipArchive::close(void) {
608	    if (isOpen()) {
609	
610	        //do not handle zipSource at all because it will be deleted by libzip
611	        //directly when not necessary anymore
612	
613	        if (!listeners.empty()) {
614	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
615	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
616	        }
617	
618	        //avoid to reset the progress when unzipping
619	        if (mode != ReadOnly) {
620	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
621	        }
622	
623	        int result = zip_close(zipHandle);
624	        if (result!=0) {
625	            //typically a cancelled commit: the archive is still open and usable, the
626	            //session is left untouched so existing entries and their copies remain valid
627	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
628	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
629	        }
630	
631	        zipHandle = nullptr;
632	        //the opening really ended (even if the buffer readback below fails afterwards):
633	        //all entries obtained during it must expire now
634	        endEntrySession();
635	        //the commit consumed the sources: the buffers adopted with freeData=true are
636	        //no longer referenced by libzip and are released exactly once, here
637	        releaseAdoptedBuffers();
638	        //the staging files of stream-written entries are not needed anymore either
639	        //(on a failed commit, e.g. a cancellation, they are kept so that a later
640	        //close can still commit the staged content)
641	        releaseStagedStreamFiles();
642	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
643	
644	        //push back the changes in the buffer
645	        int res_code = LIBZIPPP_OK;
646	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
647	            int srcOpen = zip_source_open(zipSource);
648	            if (srcOpen==0) {
649	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
650	                //buffer. We must never read into nor realloc *bufferData here: that memory
651	                //is the storage backing the libzip source we are currently reading from.
652	                //Reusing it aliases the source and, depending on the libzip version (i.e.
653	                //whether it takes ownership of the buffer when writing), it makes
654	                //zip_source_free() release a buffer that realloc() already moved/freed,
655	                //which results in a double-free (see double_free_report / fromWritableBuffer).
656	                zip_int64_t increment = 1024;
657	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
658	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
659	                char* tempBuffer = outBuffer;
660	                zip_int64_t tempBufferSize = capacity;
661	                zip_int64_t totalRead = 0;
662	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
663	                while(read>0) {
664	                    totalRead += read;
665	                    if (totalRead>=capacity) {
666	                        zip_int64_t newCapacity = capacity + increment;
667	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
668	                        if (grownBuffer==nullptr) {
669	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
670	                            ::free(outBuffer);
671	                            outBuffer = nullptr;
672	                            read = -1;
673	                            break;
674	                        }
675	                        outBuffer = grownBuffer;
676	                        capacity = newCapacity;
677	                    }
678	                    tempBuffer = outBuffer+totalRead;
679	                    tempBufferSize = capacity-totalRead;
680	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
681	                }
682	
683	                zip_source_close(zipSource);
684	
685	                if (outBuffer!=nullptr && read>=0) {
686	                    //freeing zipSource first guarantees libzip has released whatever it owns
687	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
688	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
689	                    zip_source_free(zipSource);
690	                    zipSource = nullptr;
691	
692	                    ::free(*bufferData);
693	                    *bufferData = outBuffer;
694	                    bufferLength = totalRead;
695	                } else {
696	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
697	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
698	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
699	                    zip_source_free(zipSource);
700	                    zipSource = nullptr;
701	                }
702	            } else {
703	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
704	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
705	
706	                zip_source_free(zipSource);
707	                zipSource = nullptr;
708	            }
709	        }
710	
711	        mode = NotOpen;
712	        return res_code;
713	    }
714	
715	    return LIBZIPPP_OK;
716	}
