718	void ZipArchive::discard(void) {
719	    if (isOpen()) {
720	        zip_discard(zipHandle);
721	        zipHandle = nullptr;
722	
723	        //the pending sources are gone: release the buffers adopted with freeData=true
724	        releaseAdoptedBuffers();
725	
726	        //and the files staging stream-written entries
727	        releaseStagedStreamFiles();
728	
729	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
730	            zip_source_free(zipSource);
731	            zipSource = nullptr;
732	        }
733	
734	        mode = NotOpen;
735	        endEntrySession(); //discarded opening: all its entries expire
736	    }
737	}
