768	bool ZipArchive::setEntryCompressionConfig(ZipEntry& entry, CompressionMethod comp, libzippp_uint32 level) const {
769	    if (!isOpen()) { return false; }
770	    if (!isEntryUsable(entry)) { return false; }
771	    if (mode==ReadOnly) { return false; }
772	    const libzippp_uint16 comp_libzip = convertCompressionToLibzip(comp);
773	
774	    //libzip does not reject an out-of-range DEFLATE level: the documented range is
775	    //enforced beforehand so that a failure leaves both the entry and the archive untouched
776	    if (!isCompressionLevelApplicable(comp_libzip, level)) { return false; }
777	
778	    bool success = zip_set_file_compression(zipHandle, entry.index, compressionMethodToLibzip(comp_libzip), level)==0;
779	    if (success) {
780	        entry.compressionMethod = comp_libzip;
781	        entry.compressionLevel = level;
782	        //remember the staged configuration for this opening: libzip cannot report the
783	        //level back and reports ZIP_CM_DEFAULT as STORE in the current state
784	        entryCompressionMethods[entry.index] = comp_libzip;
785	        entryCompressionLevels[entry.index] = level;
786	    }
787	    return success;
788	}
