790	bool ZipArchive::setEntryCompressionMethod(ZipEntry& entry, CompressionMethod comp) const {
791	    if (!isOpen()) { return false; }
792	    if (!isEntryUsable(entry)) { return false; }
793	    if (mode==ReadOnly) { return false; }
794	
795	    //only the method changes: the level currently in effect for the entry is re-applied,
796	    //so a level staged through another copy of the entry is preserved
797	    libzippp_uint32 level = 0;
798	    map<libzippp_uint64, libzippp_uint32>::const_iterator it = entryCompressionLevels.find(entry.index);
799	    if (it!=entryCompressionLevels.end()) { level = it->second; }
800	    return setEntryCompressionConfig(entry, comp, level);
801	}
802	
803	bool ZipArchive::setEntryCompressionLevel(ZipEntry& entry, libzippp_uint32 level) const {
804	    if (!isOpen()) { return false; }
805	    if (!isEntryUsable(entry)) { return false; }
806	    if (mode==ReadOnly) { return false; }
807	
808	    //only the level changes: the method currently in effect for the entry is re-applied,
809	    //so a method staged through another copy of the entry is preserved
810	    libzippp_uint16 method;
811	    map<libzippp_uint64, libzippp_uint16>::const_iterator it = entryCompressionMethods.find(entry.index);
812	    if (it!=entryCompressionMethods.end()) {
813	        method = it->second;
814	    } else {
815	        /*
816	         * No method was explicitly staged on the entry during this opening: the effective
817	         * method is the one libzip will use when the changes are committed. An untouched
818	         * entry keeps its committed method (visible in the current state); an entry whose
819	         * content was added or replaced during this opening falls back to the libzip
820	         * default (its current method is merely reported as STORE by libzip, which only
821	         * means "no compression change staged" here).
822	         */
823	        struct zip_stat currentStat;
824	        struct zip_stat originalStat;
825	        zip_stat_init(&currentStat);
826	        zip_stat_init(&originalStat);
827	        bool hasCurrent = zip_stat_index(zipHandle, entry.index, ZIP_FL_ENC_GUESS, &currentStat)==0;
828	        bool hasOriginal = zip_stat_index(zipHandle, entry.index, LIBZIPPP_ORIGINAL_STATE_FLAGS, &originalStat)==0;
829	        if (hasCurrent && currentStat.comp_method!=(libzippp_uint16)ZIP_CM_STORE) {
830	            method = currentStat.comp_method;
831	        } else if (hasOriginal && originalStat.comp_method==(libzippp_uint16)ZIP_CM_STORE) {
832	            method = (libzippp_uint16)ZIP_CM_STORE; //an untouched entry stored without compression
833	        } else {
834	            method = (libzippp_uint16)ZIP_CM_DEFAULT; //new or replaced entry: libzip default
835	        }
836	    }
837	    return setEntryCompressionConfig(entry, convertCompressionFromLibzip(method), level);
838	}
