852	ZipEntry ZipArchive::createEntry(struct zip_stat* stat, State state) const {
853	    string name(stat->name);
854	    libzippp_uint64 index = stat->index;
855	    libzippp_uint64 size = stat->size;
856	
857	    /*
858	     * The compression method always comes from the entry itself, in the requested state:
859	     * the archive default compression is only a template for the files added or
860	     * overwritten afterwards and must never mask the method of an existing entry. A
861	     * configuration explicitly staged during this opening wins over the stat because
862	     * libzip reports ZIP_CM_DEFAULT as STORE in the current state and cannot report the
863	     * compression level at all (a level is not stored in the archive, hence it is zero
864	     * unless it was explicitly set during this opening).
865	     */
866	    libzippp_uint16 compMethod = stat->comp_method;
867	    libzippp_uint32 compLevel = 0;
868	    if (state==Current) {
869	        map<libzippp_uint64, libzippp_uint16>::const_iterator mit = entryCompressionMethods.find(index);
870	        if (mit!=entryCompressionMethods.end()) { compMethod = mit->second; }
871	        map<libzippp_uint64, libzippp_uint32>::const_iterator lit = entryCompressionLevels.find(index);
872	        if (lit!=entryCompressionLevels.end()) { compLevel = lit->second; }
873	    }
874	
875	    libzippp_uint16 encMethod = stat->encryption_method;
876	    libzippp_uint64 sizeComp = stat->comp_size;
877	    int crc = stat->crc;
878	    time_t time = stat->mtime;
879	
880	    return ZipEntry(this, entrySession, name, index, time, compMethod, compLevel, encMethod, size, sizeComp, crc);
881	}
