883	int ZipArchive::stateFlags(State state) {
884	    return state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
885	}
886	
887	ZipEntry ZipArchive::resolveEntry(const ZipEntry& zipEntry, State state, libzippp_uint64* outSize) const {
888	    if (outSize!=nullptr) { *outSize = 0; }
889	
890	    //a null-ZipEntry (e.g. obtained through getEntry in a state where the name does not
891	    //exist) cannot be resolved in any state, nor can an entry coming from another archive
892	    //or from an opening that has ended
893	    if (!isEntryUsable(zipEntry)) { return ZipEntry(); }
894	
895	    int flag = stateFlags(state);
896	    struct zip_stat stat;
897	    zip_stat_init(&stat);
898	
899	    //stat the (stable) slot in the requested state: this fails for an entry deleted in the
900	    //current state (read with Current) or a newly added entry (read with Original)
901	    if (zip_stat_index(zipHandle, zipEntry.getIndex(), flag, &stat)!=0) { return ZipEntry(); }
902	
903	    ZipEntry resolved = createEntry(&stat, state);
904	    if (outSize!=nullptr) { *outSize = stat.size; }
905	    return resolved;
906	}
