908	vector<ZipEntry> ZipArchive::getEntries(State state) const {
909	    if (!isOpen()) { return vector<ZipEntry>(); }
910	
911	    struct zip_stat stat;
912	    zip_stat_init(&stat);
913	
914	    vector<ZipEntry> entries;
915	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
916	    libzippp_int64 nbEntries = getNbEntries(state);
917	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
918	        int result = zip_stat_index(zipHandle, i, flag, &stat);
919	        if (result==0) {
920	            ZipEntry entry = createEntry(&stat, state);
921	            entries.push_back(entry);
922	        } else {
923	            //TODO handle read error => crash ?
924	        }
925	    }
926	    return entries;
927	}
