942	ZipEntry ZipArchive::getEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
943	    if (isOpen()) {
944	        int flags = 0;
945	        if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
946	        if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
947	        if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
948	        else { flags = flags | ZIP_FL_ENC_GUESS; }
949	
950	        libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
951	        if (index>=0) {
952	            //the located index must be stat'd in the SAME state: locating a renamed entry
953	            //in the original state gives the original slot, whose name and size are the
954	            //original ones (using the current stat here would return the new name/length)
955	            return getEntry(index, state);
956	        } else {
957	            //name not found in the requested state
958	        }
959	    }
960	    return ZipEntry();
961	}
