1000	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
1001	    if (!isOpen()) { return nullptr; }
1002	    if (!isEntryUsable(zipEntry)) { return nullptr; }
1003	
1004	    //resolve the entry in the requested state: the uncompressed size and the existence of
1005	    //the entry depend on the state (a replacement may be longer, shorter or empty, a deleted
1006	    //entry is only readable as Original and a newly added one only as Current)
1007	    libzippp_uint64 entrySize = 0;
1008	    ZipEntry resolved = resolveEntry(zipEntry, state, &entrySize);
1009	    if (resolved.isNull()) { return nullptr; }
1010	
1011	    int flag = stateFlags(state);
1012	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1013	    if (zipFile) {
1014	        //zero means "read the whole content" and a too big length returns all of it; the
1015	        //captured zipEntry size is intentionally never used to bound the read
1016	        libzippp_uint64 uisize = size==0 || size>entrySize ? entrySize : size;
1017	
1018	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
1019	        if (!data) { //allocation error
1020	            zip_fclose(zipFile);
1021	            return nullptr;
1022	        }
1023	
1024	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
1025	        zip_fclose(zipFile);
1026	
1027	        //avoid buffer copy
1028	        if (asText) { data[uisize] = '\0'; }
1029	
1030	        libzippp_int64 isize = (libzippp_int64)uisize;
1031	        if (result==isize) {
1032	            return data;
1033	        } else { //unexpected number of bytes read => crash ?
1034	            delete[] data;
1035	        }
1036	    } else {
1037	        //unable to read the entry (e.g. it does not exist in the requested state) => crash ?
1038	    }
1039	
1040	    return nullptr;
1041	}
1042	
1043	void* ZipArchive::readEntry(const string& zipEntry, bool asText, State state, libzippp_uint64 size) const {
1044	    //the name is interpreted in the requested state: there is no fallback to the other state
1045	    //if the name does not exist in this one
1046	    ZipEntry entry = getEntry(zipEntry, false, true, state);
1047	    if (entry.isNull()) { return nullptr; }
1048	    return readEntry(entry, asText, state, size);
1049	}
