1051	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
1052	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1053	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1054	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
1055	
1056	    if (entry.isFile()) {
1057	        int result = zip_delete(zipHandle, entry.getIndex());
1058	        if (result==0) {
1059	            forgetEntryCompressionConfig(entry.getIndex());
1060	            forgetStagedStreamFile(entry.getIndex());
1061	            return 1;
1062	        }
1063	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
1064	    } else {
1065	        int counter = 0;
1066	        vector<ZipEntry> allEntries = getEntries();
1067	        vector<ZipEntry>::const_iterator eit;
1068	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
1069	            ZipEntry ze = *eit;
1070	            string::size_type startPosition = ze.getName().find(entry.getName());
1071	            if (startPosition==0) {
1072	                int result = zip_delete(zipHandle, ze.getIndex());
1073	                if (result==0) {
1074	                    forgetEntryCompressionConfig(ze.getIndex());
1075	                    forgetStagedStreamFile(ze.getIndex());
1076	                    ++counter;
1077	                }
1078	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
1079	            }
1080	        }
1081	        return counter;
1082	    }
1083	}
