1085	int ZipArchive::deleteEntry(const string& e) const {
1086	    ZipEntry entry = getEntry(e);
1087	    if (entry.isNull()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1088	    return deleteEntry(entry);
1089	}
