1091	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newNameIn) const {
1092	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1093	    if (!isEntryUsable(entry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1094	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
1095	    if (newNameIn.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1096	
1097	    bool isDir = entry.isDirectory();
1098	    string newName = newNameIn;
1099	    if (isDir) {
1100	        //a '/' is automatically appended to the destination of a directory
1101	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { newName += LIBZIPPP_ENTRY_PATH_SEPARATOR; }
1102	    } else {
1103	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //a file cannot be renamed as a directory
1104	    }
1105	
1106	    string sourceName = entry.getName();
1107	    if (newName==sourceName) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1108	
1109	    /*
1110	     * Enumerate ALL the entries of the CURRENT state of the archive (i.e. including any
1111	     * uncommitted addition/deletion/replacement/rename). Slots freed by zip_delete are
1112	     * reported with a null name by libzip and simply skipped.
1113	     */
1114	    struct RenameItem {
1115	        zip_uint64_t index;
1116	        string oldName;
1117	        string targetName;
1118	    };
1119	    vector<RenameItem> movedItems;
1120	    vector<string> externalNames;
1121	
1122	    zip_int64_t nbSlots = zip_get_num_entries(zipHandle, 0);
1123	    for(zip_int64_t i=0 ; i<nbSlots ; ++i) {
1124	        const char* currentName = zip_get_name(zipHandle, (zip_uint64_t)i, ZIP_FL_ENC_GUESS);
1125	        if (currentName==nullptr) { continue; } //entry deleted in the current (uncommitted) state
1126	
1127	        string name(currentName);
1128	        bool participates = false;
1129	        string targetName;
1130	        if (isDir) {
1131	            if (name==sourceName) {
1132	                participates = true;
1133	                targetName = newName;
1134	            } else if (name.compare(0, sourceName.length(), sourceName)==0) {
1135	                participates = true; //descendant of the moved directory
1136	                targetName = newName + name.substr(sourceName.length());
1137	            }
1138	        } else {
1139	            participates = (name==sourceName);
1140	            targetName = newName;
1141	        }
1142	
1143	        if (participates) {
1144	            movedItems.push_back(RenameItem{(zip_uint64_t)i, name, targetName});
1145	        } else {
1146	            externalNames.push_back(name);
1147	        }
1148	    }
1149	
1150	    //the source entry itself must be part of the current archive
1151	    bool sourceFound = false;
1152	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1153	        if (it->oldName==sourceName) { sourceFound = true; break; }
1154	    }
1155	    if (!sourceFound) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1156	
1157	    /*
1158	     * Detect conflicts against the CURRENT state only: any entry that does not participate
1159	     * in the move must not occupy the destination itself nor lie below it. Entries whose
1160	     * parent directories are only implicit (no explicit directory entry in the archive) are
1161	     * listed here as well, so a file such as new/target/last.txt prevents src/ from being
1162	     * moved to new/target/ even when no new/ or new/target/ directory entry exists.
1163	     */
1164	    for(vector<string>::const_iterator it=externalNames.begin() ; it!=externalNames.end() ; ++it) {
1165	        const string& external = *it;
1166	        if (isDir) {
1167	            if (external==newName || external.compare(0, newName.length(), newName)==0) {
1168	                return LIBZIPPP_ERROR_UNKNOWN; //destination already occupied by an external entry: no overwrite, no merge
1169	            }
1170	        } else {
1171	            if (external==newName) {
1172	                return LIBZIPPP_ERROR_UNKNOWN; //the destination file already exists
1173	            }
1174	        }
1175	    }
1176	
1177	    /*
1178	     * Compute the (explicit) parent directories that will be missing once the entries have
1179	     * been moved. A directory that is itself moved never has to be re-created here (it keeps
1180	     * existing as an entry, only its name changes), even when a moved entry's new parent
1181	     * chain goes through it.
1182	     */
1183	    vector<string> parentsToCreate;
1184	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1185	        //for a directory target (ending with '/'), the first parent to consider is above the
1186	        //target directory itself, hence the search starts at the penultimate separator
1187	        string::size_type searchPos = it->targetName.length()-1;
1188	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(it->targetName) && searchPos>0) { searchPos -= 1; }
1189	        string::size_type slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, searchPos);
1190	        while(slash!=string::npos && slash>0) {
1191	            string parent = it->targetName.substr(0, slash+1);
1192	
1193	            //a moved destination already exists as an entry after the move
1194	            bool isMovedDestination = false;
1195	            for(vector<RenameItem>::const_iterator mit=movedItems.begin() ; mit!=movedItems.end() ; ++mit) {
1196	                if (mit->targetName==parent) { isMovedDestination = true; break; }
1197	            }
1198	            if (isMovedDestination) { break; } //all the ancestors above are shared with this moved directory
1199	
1200	            //an external entry already provides the directory (explicitly)
1201	            bool isExternal = false;
1202	            for(vector<string>::const_iterator eit=externalNames.begin() ; eit!=externalNames.end() ; ++eit) {
1203	                if (*eit==parent) { isExternal = true; break; }
1204	            }
1205	            if (isExternal) { break; } //the prefix chain up to this directory already exists
1206	
1207	            bool alreadyScheduled = false;
1208	            for(vector<string>::const_iterator pit=parentsToCreate.begin() ; pit!=parentsToCreate.end() ; ++pit) {
1209	                if (*pit==parent) { alreadyScheduled = true; break; }
1210	            }
1211	            if (!alreadyScheduled) { parentsToCreate.push_back(parent); }
1212	            slash = it->targetName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, slash-1);
1213	        }
1214	    }
1215	    //create the parents from the shallowest to the deepest
1216	    std::sort(parentsToCreate.begin(), parentsToCreate.end());
1217	
1218	    /*
1219	     * Apply the rename deepest-first. This ordering is what makes moving a directory below
1220	     * its own path possible (e.g. a/ to a/b/): the descendants free the names the ancestors
1221	     * are renamed to, and the freshly re-created parent directories are not touched.
1222	     */
1223	    std::sort(movedItems.begin(), movedItems.end(),
1224	              [](const RenameItem& a, const RenameItem& b) { return a.targetName > b.targetName; });
1225	
1226	    vector<zip_uint64_t> renamedIndices;
1227	    vector<string> renamedOldNames;
1228	    bool failure = false;
1229	    for(vector<RenameItem>::const_iterator it=movedItems.begin() ; it!=movedItems.end() ; ++it) {
1230	        int result = zip_file_rename(zipHandle, it->index, it->targetName.c_str(), ZIP_FL_ENC_GUESS);
1231	        if (result!=0) { failure = true; break; }
1232	        renamedIndices.push_back(it->index);
1233	        renamedOldNames.push_back(it->oldName);
1234	    }
1235	
1236	    //create the missing parent directories (e.g. re-create a/ when a/ moved to a/b/)
1237	    vector<zip_uint64_t> createdDirIndices;
1238	    if (!failure) {
1239	        for(vector<string>::const_iterator it=parentsToCreate.begin() ; it!=parentsToCreate.end() ; ++it) {
1240	            zip_int64_t dirIndex = zip_dir_add(zipHandle, it->c_str(), ZIP_FL_ENC_GUESS);
1241	            if (dirIndex<0) { failure = true; break; }
1242	            createdDirIndices.push_back((zip_uint64_t)dirIndex);
1243	        }
1244	    }
1245	
1246	    if (failure) {
1247	        /*
1248	         * The move could not be completed: undo everything done during THIS call so that the
1249	         * archive is restored to its exact pre-call state. The directories created during
1250	         * the move are removed first (they may occupy the original names), then the renames
1251	         * are replayed in the reverse order (shallowest-first). Any other pending change is
1252	         * left untouched.
1253	         */
1254	        for(vector<zip_uint64_t>::reverse_iterator dit=createdDirIndices.rbegin() ; dit!=createdDirIndices.rend() ; ++dit) {
1255	            zip_delete(zipHandle, *dit);
1256	        }
1257	        for(zip_int64_t k=(zip_int64_t)renamedIndices.size()-1 ; k>=0 ; --k) {
1258	            zip_file_rename(zipHandle, renamedIndices[(size_t)k], renamedOldNames[(size_t)k].c_str(), ZIP_FL_ENC_GUESS);
1259	        }
1260	        return LIBZIPPP_ERROR_UNKNOWN;
1261	    }
1262	
1263	    return (int)movedItems.size();
1264	}
