1286	void ZipArchive::forgetStagedStreamFile(libzippp_uint64 index) const {
1287	    map<libzippp_uint64, FILE*>::iterator it = stagedStreamFiles.find(index);
1288	    if (it!=stagedStreamFiles.end()) {
1289	        //the source of the entry is gone (deleted or replaced): libzip never closes
1290	        //the staging file itself, so it is closed exactly once, here
1291	        fclose(it->second);
1292	        stagedStreamFiles.erase(it);
1293	    }
1294	}
1295	
1296	bool ZipArchive::isArchiveCompressionApplicable(void) const {
1297	    if (!useArchiveCompressionMethod && compressionLevel==0) { return true; }
1298	
1299	    //a non-zero default level must be applicable to the default method: libzip does not
1300	    //reject an out-of-range DEFLATE level (it would be written as-is), so the documented
1301	    //range is enforced here, before anything is modified
1302	    libzippp_uint16 effectiveMethod = useArchiveCompressionMethod ? compressionMethod : (libzippp_uint16)ZIP_CM_DEFAULT;
1303	    if (!isCompressionLevelApplicable(effectiveMethod, compressionLevel)) { return false; }
1304	
1305	#ifdef LIBZIPPP_HAS_COMPRESSION_METHOD_SUPPORTED
1306	    if (useArchiveCompressionMethod) {
1307	        return zip_compression_method_supported(compressionMethodToLibzip(compressionMethod), 1)!=0;
1308	    }
1309	#endif
1310	    return true;
1311	}
1312	
1313	bool ZipArchive::isArchiveEncryptionApplicable(void) const {
1314	#ifdef LIBZIPPP_WITH_ENCRYPTION
1315	    if (isEncrypted()) {
1316	  #ifdef LIBZIPPP_HAS_ENCRYPTION_METHOD_SUPPORTED
1317	        return zip_encryption_method_supported((zip_uint16_t)encryptionMethod, 1)!=0;
1318	  #else
1319	        //cannot be checked beforehand: a failure is rolled back after the addition
1320	        return true;
1321	  #endif
1322	    }
1323	#endif
1324	    return true;
1325	}
1326	
1327	bool ZipArchive::createParentDirectories(const string& entryName, vector<libzippp_uint64>& createdDirIndices) const {
1328	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1329	    if (lastSlash==string::npos) { return true; } //no parent directory needed
1330	
1331	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1332	    while (nextSlash!=string::npos && nextSlash<=lastSlash) {
1333	        string pathToCreate = entryName.substr(0, nextSlash+1);
1334	        if (!hasEntry(pathToCreate)) {
1335	            libzippp_int64 dirIndex = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1336	            if (dirIndex<0) {
1337	                //a failed addition must not leave empty parent directories behind
1338	                rollbackCreatedDirectories(createdDirIndices);
1339	                return false;
1340	            }
1341	            createdDirIndices.push_back((libzippp_uint64)dirIndex);
1342	        }
1343	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1344	    }
1345	    return true;
1346	}
1347	
1348	void ZipArchive::rollbackCreatedDirectories(const vector<libzippp_uint64>& createdDirIndices) const {
1349	    //deepest directory first; only the directories created by the failed call are
1350	    //removed, pre-existing ones are never touched
1351	    for(vector<libzippp_uint64>::const_reverse_iterator it=createdDirIndices.rbegin() ; it!=createdDirIndices.rend() ; ++it) {
1352	        zip_delete(zipHandle, *it);
1353	    }
1354	}
1355	
1356	bool ZipArchive::installPreparedSource(const string& entryName, zip_source* source, const vector<libzippp_uint64>& createdDirIndices, libzippp_uint64* addedIndex) const {
1357	    libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
1358	    if (result<0) {
1359	        //the source was not adopted by libzip: release it without touching its data
1360	        zip_source_free(source);
1361	        rollbackCreatedDirectories(createdDirIndices);
1362	        return false;
1363	    }
1364	
1365	    zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
1366	
1367	    bool settingsApplied = true;
1368	    bool compressionStaged = false;
1369	    if (useArchiveCompressionMethod || compressionLevel!=0) {
1370	        //both the default method and the default level selected on the archive apply to
1371	        //the actual write (a zero level keeps the default behaviour of libzip)
1372	        settingsApplied = zip_set_file_compression(zipHandle, result, compressionMethodToLibzip(compressionMethod), compressionLevel)==0;
1373	        compressionStaged = settingsApplied;
1374	    }
1375	#ifdef LIBZIPPP_WITH_ENCRYPTION
1376	    if (settingsApplied && isEncrypted()) {
1377	        settingsApplied = zip_file_set_encryption(zipHandle, result, encryptionMethod, nullptr)==0;
1378	    }
1379	#endif
1380	
1381	    if (!settingsApplied) {
1382	        /*
1383	         * Last-resort rollback: the applicability of the selected compression and
1384	         * encryption methods was checked before anything was changed, so this is only
1385	         * reachable on an unexpected libzip failure. The entry is reverted and the
1386	         * directories created by this call are removed; every other pending change
1387	         * (other entries, deletions, renames, comments) is left untouched. Reverting
1388	         * the entry also frees the source (which never owns the caller's data here).
1389	         */
1390	        zip_unchange(zipHandle, (zip_uint64_t)result);
1391	        rollbackCreatedDirectories(createdDirIndices);
1392	        return false;
1393	    }
1394	
1395	    if (compressionStaged) {
1396	        //the archive defaults were applied to the entry: they are its staged compression
1397	        //configuration for the rest of this opening (see entryCompressionMethods)
1398	        entryCompressionMethods[(libzippp_uint64)result] = compressionMethod;
1399	        entryCompressionLevels[(libzippp_uint64)result] = compressionLevel;
1400	    }
1401	    if (addedIndex!=nullptr) { *addedIndex = (libzippp_uint64)result; }
1402	    return true;
1403	}
1404	
1405	bool ZipArchive::addFile(const string& entryName, const string& file) const {
1406	    if (!isOpen()) { return false; }
1407	    if (mode==ReadOnly) { return false; } //adding not allowed
1408	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1409	
1410	    //the source file must be readable: a missing file must not leave any trace
1411	    //(neither a new entry nor parent directories) in the archive
1412	    FILE* probe = fopen(file.c_str(), "rb");
1413	    if (probe==nullptr) { return false; }
1414	    fclose(probe);
1415	
1416	    //the compression and encryption methods selected on the archive must be applicable
1417	    //by this libzip: this is checked before anything is changed so that a failure
1418	    //neither leaves a new entry behind nor silently falls back to weaker settings
1419	    if (!isArchiveCompressionApplicable()) { return false; }
1420	    if (!isArchiveEncryptionApplicable()) { return false; }
1421	
1422	    vector<libzippp_uint64> createdDirIndices;
1423	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1424	
1425	    zip_source* source = zip_source_file(zipHandle, file.c_str(), 0, -1);
1426	    if (source==nullptr) {
1427	        //unable to create the zip_source
1428	        rollbackCreatedDirectories(createdDirIndices);
1429	        return false;
1430	    }
1431	    libzippp_uint64 index = 0;
1432	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) { return false; }
1433	    //a stream-staged content previously staged for this entry is not referenced
1434	    //anymore: its staging file is released (see stagedStreamFiles)
1435	    forgetStagedStreamFile(index);
1436	    return true;
1437	}
1438	
1439	bool ZipArchive::addData(const string& entryName, const void* data, libzippp_uint64 length, bool freeData) const {
1440	    if (!isOpen()) { return false; }
1441	    if (mode==ReadOnly) { return false; } //adding not allowed
1442	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1443	
1444	    //a null buffer is only valid for an empty content; anything else is rejected
1445	    //before the archive is touched (the caller keeps the ownership of the data)
1446	    if (data==nullptr && length>0) { return false; }
1447	
1448	    //see addFile: the selected compression/encryption must be applicable beforehand
1449	    if (!isArchiveCompressionApplicable()) { return false; }
1450	    if (!isArchiveEncryptionApplicable()) { return false; }
1451	
1452	    vector<libzippp_uint64> createdDirIndices;
1453	    if (!createParentDirectories(entryName, createdDirIndices)) { return false; }
1454	
1455	    /*
1456	     * The buffer is always handed to libzip with freep=0, even when freeData is true:
1457	     * the ownership is transferred to the archive (see adoptedBuffers) only once the
1458	     * data has been fully accepted. Hence a failed call never frees the caller's
1459	     * memory and a successful one guarantees the buffer is released exactly once,
1460	     * when the pending changes are committed or discarded.
1461	     */
1462	    zip_source* source = zip_source_buffer(zipHandle, data, length, 0);
1463	    if (source==nullptr) {
1464	        //unable to create the zip_source
1465	        rollbackCreatedDirectories(createdDirIndices);
1466	        return false;
1467	    }
1468	    libzippp_uint64 index = 0;
1469	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) { return false; }
1470	    //a stream-staged content previously staged for this entry is not referenced
1471	    //anymore: its staging file is released (see stagedStreamFiles)
1472	    forgetStagedStreamFile(index);
1473	
1474	    if (freeData && data!=nullptr) {
1475	        adoptedBuffers.push_back(const_cast<void*>(data));
1476	    }
1477	    return true;
1478	}
1479	
1480	bool ZipArchive::addData(const std::string& entryName, const std::basic_string<libzippp_uint8> data) const {
1481	    /*
1482	     * The argument is a copy that is destroyed when this method returns: its content
1483	     * must be copied again into a buffer owned by the archive (through the freeData
1484	     * contract) so that the staged source never references the dead argument when the
1485	     * changes are committed or read back.
1486	     */
1487	    if (data.empty()) { return addData(entryName, nullptr, 0, false); }
1488	    void* copy = malloc(data.size());
1489	    if (copy==nullptr) { return false; }
1490	    memcpy(copy, data.data(), data.size());
1491	    if (!addData(entryName, copy, data.size(), true)) {
1492	        //the ownership was not transferred: the copy is still ours to release
1493	        ::free(copy);
1494	        return false;
1495	    }
1496	    return true;
1497	}
1498	
1499	bool ZipArchive::addData(const string& entryName, std::istream& input, libzippp_uint64 chunksize) const {
1500	    if (!isOpen()) { return false; }
1501	    if (mode==ReadOnly) { return false; } //adding not allowed
1502	    if (entryName.empty()) { return false; }
1503	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1504	
1505	    //see addFile: the selected compression/encryption must be applicable beforehand;
1506	    //all the checks above happen before a single byte is consumed from the stream
1507	    if (!isArchiveCompressionApplicable()) { return false; }
1508	    if (!isArchiveEncryptionApplicable()) { return false; }
1509	
1510	    if (chunksize==0) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; }
1511	
1512	    /*
1513	     * The content is staged in a temporary file (removed by the operating system as
1514	     * soon as the file is closed) and handed to libzip through a custom source: the
1515	     * memory footprint stays bounded whatever the stream length and, once this method
1516	     * has returned, neither reading the entry nor committing depends on the stream.
1517	     */
1518	    FILE* staging = tmpfile();
1519	    if (staging==nullptr) { return false; }
1520	
1521	    char* chunk = NEW_CHAR_ARRAY(chunksize)
1522	    if (chunk==nullptr) {
1523	        fclose(staging);
1524	        return false;
1525	    }
1526	
1527	    libzippp_uint64 total = 0;
1528	    std::streamsize pending = 0; //bytes extracted by the last read, not staged yet
1529	    bool failed = false;
1530	    bool ended = false;
1531	    try {
1532	        for (;;) {
1533	            input.read(chunk, (std::streamsize)chunksize);
1534	            pending = input.gcount();
1535	            if (pending>0) {
1536	                if (fwrite(chunk, 1, (size_t)pending, staging)!=(size_t)pending) { failed = true; break; } //unable to save the read data
1537	                total += (libzippp_uint64)pending;
1538	                pending = 0;
1539	            }
1540	            if (input.eof()) { ended = true; break; } //normal end, possibly after a final partial chunk
1541	            if (input.fail() || input.bad()) { failed = true; break; } //read error (or an already unusable stream)
1542	        }
1543	    } catch (...) {
1544	        //a stream whose exceptions are enabled throws on its normal end (eofbit/failbit)
1545	        //exactly like on a read error: the stream state tells both cases apart. The
1546	        //bytes extracted before the throw are still reported by gcount() (the pending
1547	        //assignment above did not run), so they are staged too.
1548	        pending = input.gcount();
1549	        if (pending>0) {
1550	            if (fwrite(chunk, 1, (size_t)pending, staging)==(size_t)pending) { total += (libzippp_uint64)pending; }
1551	            else { failed = true; }
1552	        }
1553	        if (!failed) {
1554	            ended = input.eof() && !input.bad();
1555	            failed = !ended;
1556	        }
1557	    }
1558	    delete[] chunk;
1559	
1560	    if (failed || !ended) {
1561	        //the archive has not been touched yet: no entry, no parent directory, and the
1562	        //bytes already consumed from the stream are simply dropped
1563	        fclose(staging);
1564	        return false;
1565	    }
1566	    //a buffered write error may only surface now: the staged content must be complete
1567	    if (fflush(staging)!=0 || ferror(staging)) {
1568	        fclose(staging);
1569	        return false;
1570	    }
1571	
1572	    vector<libzippp_uint64> createdDirIndices;
1573	    if (!createParentDirectories(entryName, createdDirIndices)) {
1574	        fclose(staging);
1575	        return false;
1576	    }
1577	
1578	    IstreamSourceState* state = new (std::nothrow) IstreamSourceState;
1579	    if (state==nullptr) {
1580	        rollbackCreatedDirectories(createdDirIndices);
1581	        fclose(staging);
1582	        return false;
1583	    }
1584	    state->file = staging;
1585	    state->size = total;
1586	    state->offset = 0;
1587	    zip_error_init(&state->error);
1588	
1589	    zip_source* source = zip_source_function(zipHandle, istreamSourceCallback, state);
1590	    if (source==nullptr) {
1591	        delete state;
1592	        rollbackCreatedDirectories(createdDirIndices);
1593	        fclose(staging);
1594	        return false;
1595	    }
1596	
1597	    libzippp_uint64 index = 0;
1598	    if (!installPreparedSource(entryName, source, createdDirIndices, &index)) {
1599	        //the source (and its state) was released by the failed installation; the
1600	        //staging file is still ours
1601	        fclose(staging);
1602	        return false;
1603	    }
1604	
1605	    //a content previously staged from a stream for this very entry is not referenced
1606	    //anymore (its source was released by the overwrite): close its staging file so
1607	    //that successive overwrites of the same entry never leak
1608	    forgetStagedStreamFile(index);
1609	    stagedStreamFiles[index] = staging;
1610	    return true;
1611	}
1612	
1613	bool ZipArchive::addEntry(const string& entryName) const {
1614	    if (!isOpen()) { return false; }
1615	    if (mode==ReadOnly) { return false; } //adding not allowed
1616	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
1617	
1618	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
1619	    while (nextSlash!=string::npos) {
1620	        string pathToCreate = entryName.substr(0, nextSlash+1);
1621	        if (!hasEntry(pathToCreate)) {
1622	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
1623	            if (result==-1) { return false; }
1624	        }
1625	        nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR, nextSlash+1);
1626	    }
1627	
1628	    return true;
1629	}
1630	
1631	void ZipArchive::removeProgressListener(ZipProgressListener* listener) {
1632	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
1633	        ZipProgressListener* l = *it;
1634	        if (l==listener) {
1635	            listeners.erase(it);
1636	            break;
1637	        }
1638	    }
1639	}
1640	
1641	void ZipArchive::setCompressionMethod(CompressionMethod comp)
1642	{
1643	    useArchiveCompressionMethod = comp!=CompressionMethod::DEFAULT;
1644	    compressionMethod = convertCompressionToLibzip(comp);
1645	}
1646	
1647	CompressionMethod ZipArchive::getCompressionMethod(void) const {
1648	    return convertCompressionFromLibzip(compressionMethod);
1649	}
1650	
1651	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
1652	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
1653	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){ ofOutput.write((char*)data, size); return bool(ofOutput); };
1654	    return readEntry(zipEntry, writeFunc, state, chunksize);
1655	}
1656	
1657	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
1658	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
1659	    //null entries, entries from other archives and entries from a previous opening are
1660	    //rejected before any data delivery (the output stream/callback is left untouched)
1661	    if (!isEntryUsable(zipEntry)) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
1662	
1663	    //resolve the entry in the requested state: its existence and uncompressed size depend
1664	    //on the state. When it does not exist in the state, no data is delivered at all.
1665	    libzippp_uint64 maxSize = 0;
1666	    ZipEntry resolved = resolveEntry(zipEntry, state, &maxSize);
1667	    if (resolved.isNull()) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1668	
1669	    if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
1670	
1671	    int flag = stateFlags(state);
1672	    struct zip_file* zipFile = zip_fopen_index(zipHandle, resolved.getIndex(), flag);
1673	    if (!zipFile) { return LIBZIPPP_ERROR_FOPEN_FAILURE; }
1674	
1675	    int iRes = LIBZIPPP_OK;
1676	
1677	    //an empty content succeeds without reading anything; a single zero-length delivery is
1678	    //still signalled to the output (this matches the historical behavior)
1679	    if (maxSize==0) {
1680	        if (!writeFunc("", 0)) {
1681	            zip_fclose(zipFile);
1682	            return LIBZIPPP_ERROR_OWRITE_FAILURE;
1683	        }
1684	        zip_fclose(zipFile);
1685	        return LIBZIPPP_OK;
1686	    }
1687	
1688	    //only allocate what a single delivery may need (the whole content when it is smaller
1689	    //than the chunk size) instead of the chunk size in every case
1690	    libzippp_uint64 bufferSize = maxSize<chunksize ? maxSize : chunksize;
1691	    char* data = NEW_CHAR_ARRAY(bufferSize)
1692	    if (data!=nullptr) {
1693	        //stream the exact, state-resolved length in successive chunks: this delivers the
1694	        //whole content exactly once (chunksize bigger than, equal to, or not a divisor of
1695	        //the content length are all handled by the same loop)
1696	        libzippp_uint64 remaining = maxSize;
1697	        while (remaining>0) {
1698	            libzippp_uint64 toRead = remaining<bufferSize ? remaining : bufferSize;
1699	            libzippp_int64 result = zip_fread(zipFile, data, toRead);
1700	            if (result<0) {
1701	                iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1702	                break;
1703	            }
1704	            if (static_cast<libzippp_uint64>(result)!=toRead) {
1705	                iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1706	                break;
1707	            }
1708	            if (!writeFunc(data, toRead)) {
1709	                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1710	                break;
1711	            }
1712	            remaining -= toRead;
1713	        }
1714	        delete[] data;
1715	    } else {
1716	        iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1717	    }
1718	    zip_fclose(zipFile);
1719	    return iRes;
1720	}
