#include "libzippp.h"
#include <cassert>
#include <cstdio>
#include <iostream>
#include <string>

using namespace libzippp;

static int failures = 0;
#define CHECK(cond) do { \
    if (!(cond)) { ++failures; \
        std::cerr << "FAIL line " << __LINE__ << ": " << #cond << std::endl; } \
} while (0)

static bool has(ZipArchive& z, const std::string& name) {
    return z.hasEntry(name, false, true, ZipArchive::Current);
}

int main(void) {
    const char* path = "/tmp/task007_test.zip";
    remove(path);

    // ---- scenario 1: dir moved, old name reused, saved objects follow the entry ----
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        z.addData("a/f.txt", "content-f", 9);
        z.addData("a/g.txt", "content-g", 9);

        ZipEntry dirA = z.getEntry("a/");
        ZipEntry fileF = z.getEntry("a/f.txt");
        ZipEntry dirAcopy = dirA; // a copy must behave the same
        assert(!dirA.isNull() && !fileF.isNull());

        CHECK(z.renameEntry(dirA, "b/") == 3); // a/ + a/f.txt + a/g.txt
        CHECK(has(z, "b/") && has(z, "b/f.txt") && has(z, "b/g.txt"));

        // re-create a new a/ with its own file
        z.addData("a/new.txt", "brand-new", 9);
        CHECK(has(z, "a/") && has(z, "a/new.txt"));

        // rename the SAVED directory object to c/: must move b/'s current content,
        // leave the new a/ untouched
        CHECK(z.renameEntry(dirAcopy, "c/") == 3);
        CHECK(has(z, "c/") && has(z, "c/f.txt") && has(z, "c/g.txt"));
        CHECK(has(z, "a/") && has(z, "a/new.txt"));
        CHECK(!has(z, "b/"));

        // the saved file object now points at c/f.txt
        CHECK(fileF.readAsText() == "content-f");

        // and can be renamed individually
        CHECK(z.renameEntry(fileF, "c/renamed.txt") == 1);
        CHECK(has(z, "c/renamed.txt") && !has(z, "c/f.txt"));
        CHECK(fileF.readAsText() == "content-f");

        // renaming to the entry's CURRENT name is invalid
        CHECK(z.renameEntry(fileF, "c/renamed.txt") == LIBZIPPP_ERROR_INVALID_PARAMETER);
        CHECK(z.renameEntry(dirA, "c") == LIBZIPPP_ERROR_INVALID_PARAMETER);

        // delete the saved file object
        CHECK(z.deleteEntry(fileF) == 1);
        CHECK(!has(z, "c/renamed.txt"));

        // deleting it again: the entry is gone -> INVALID_ENTRY
        CHECK(z.deleteEntry(fileF) == LIBZIPPP_ERROR_INVALID_ENTRY);
        CHECK(z.renameEntry(fileF, "c/other.txt") == LIBZIPPP_ERROR_INVALID_ENTRY);

        // delete the saved directory object: removes its current dir + current subentries
        CHECK(z.deleteEntry(dirA) == 2); // c/ + c/g.txt
        CHECK(!has(z, "c/"));
        CHECK(has(z, "a/") && has(z, "a/new.txt"));

        // dirA is now deleted: INVALID_ENTRY even though nothing reused the name
        CHECK(z.deleteEntry(dirA) == LIBZIPPP_ERROR_INVALID_ENTRY);
        CHECK(z.renameEntry(dirA, "d/") == LIBZIPPP_ERROR_INVALID_ENTRY);

        CHECK(z.close() == LIBZIPPP_OK);

        // reopen: the committed result must reflect the whole chain
        ZipArchive z2(path);
        z2.open(ZipArchive::ReadOnly);
        CHECK(z2.hasEntry("a/") && z2.hasEntry("a/new.txt"));
        CHECK(!z2.hasEntry("b/") && !z2.hasEntry("c/"));
        ZipEntry nf = z2.getEntry("a/new.txt");
        CHECK(nf.readAsText() == "brand-new");
        z2.close();
    }

    // ---- scenario 2: plain file whose old name gets reused ----
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        z.addData("x.txt", "original", 8);
        ZipEntry fx = z.getEntry("x.txt");
        CHECK(z.renameEntry(fx, "y.txt") == 1);
        z.addData("x.txt", "reused", 6); // new entry reuses the old name

        // operations on the saved object must hit y.txt, never the new x.txt
        CHECK(fx.readAsText() == "original");
        CHECK(z.renameEntry(fx, "z.txt") == 1);
        CHECK(has(z, "z.txt") && has(z, "x.txt"));
        CHECK(z.getEntry("x.txt").readAsText() == "reused");
        CHECK(z.deleteEntry(fx) == 1);
        CHECK(!has(z, "z.txt") && has(z, "x.txt"));

        // fx is deleted; its old name is free and its even-older name is taken
        CHECK(z.deleteEntry(fx) == LIBZIPPP_ERROR_INVALID_ENTRY);
        CHECK(z.renameEntry(fx, "w.txt") == LIBZIPPP_ERROR_INVALID_ENTRY);
        CHECK(z.close() == LIBZIPPP_OK);
    }

    // ---- scenario 3: directory moved below itself, auto-created parent ----
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        z.addData("m/inner.txt", "inner", 5);
        ZipEntry dirM = z.getEntry("m/");
        CHECK(z.renameEntry(dirM, "m/sub/") == 2); // m/ -> m/sub/, parent m/ re-created
        CHECK(has(z, "m/") && has(z, "m/sub/") && has(z, "m/sub/inner.txt"));

        // the saved object follows the moved directory, not the auto-created parent
        CHECK(z.renameEntry(dirM, "n/") == 2);
        CHECK(has(z, "n/") && has(z, "n/inner.txt"));
        CHECK(has(z, "m/") && !has(z, "m/sub/"));
        CHECK(z.deleteEntry(dirM) == 2);
        CHECK(!has(z, "n/") && has(z, "m/"));
        CHECK(z.close() == LIBZIPPP_OK);
    }

    // ---- scenario 4: conflict keeps state, object stays usable ----
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        z.addData("p/data.txt", "pdata", 5);
        z.addData("q/data.txt", "qdata", 5);
        ZipEntry dirP = z.getEntry("p/");
        ZipEntry fileP = z.getEntry("p/data.txt");

        // destination occupied -> UNKNOWN, everything unchanged
        CHECK(z.renameEntry(dirP, "q/") == LIBZIPPP_ERROR_UNKNOWN);
        CHECK(has(z, "p/") && has(z, "p/data.txt"));
        CHECK(has(z, "q/") && has(z, "q/data.txt"));
        CHECK(z.getEntry("q/data.txt").readAsText() == "qdata");

        // file-level conflict too
        CHECK(z.renameEntry(fileP, "q/data.txt") == LIBZIPPP_ERROR_UNKNOWN);
        CHECK(has(z, "p/data.txt"));

        // the object is still usable for a legal operation afterwards
        CHECK(z.renameEntry(dirP, "r/") == 2);
        CHECK(has(z, "r/") && has(z, "r/data.txt"));
        CHECK(fileP.readAsText() == "pdata");
        CHECK(z.close() == LIBZIPPP_OK);

        ZipArchive z2(path);
        z2.open(ZipArchive::ReadOnly);
        CHECK(z2.hasEntry("r/data.txt"));
        CHECK(z2.getEntry("r/data.txt").readAsText() == "pdata");
        z2.close();
    }

    // ---- scenario 5: Original-state object writes hit the Current version ----
    {
        ZipArchive z(path);
        z.open(ZipArchive::Write);
        z.addData("s/file.txt", "sdata", 5);
        z.close();

        z.open(ZipArchive::Write);
        ZipEntry orig = z.getEntry("s/file.txt", false, true, ZipArchive::Original);
        ZipEntry origDir = z.getEntry("s/", false, true, ZipArchive::Original);
        assert(!orig.isNull() && !origDir.isNull());
        CHECK(z.renameEntry(orig, "s/moved.txt") == 1);
        CHECK(has(z, "s/moved.txt") && !has(z, "s/file.txt"));
        CHECK(orig.readAsText() == "sdata");
        // Original view still shows the original content
        CHECK(orig.readAsText(ZipArchive::Original) == "sdata");
        CHECK(z.getEntry("s/file.txt", false, true, ZipArchive::Original).readAsText(ZipArchive::Original) == "sdata");
        CHECK(z.renameEntry(origDir, "t/") == 2);
        CHECK(has(z, "t/moved.txt"));
        CHECK(z.deleteEntry(orig) == 1);
        CHECK(!has(z, "t/moved.txt"));
        CHECK(z.close() == LIBZIPPP_OK);
    }

    // ---- scenario 6: membership decided at call time (Current) ----
